INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62896116', 62896116, 'analyze_legacy', 'Kementerian Pendidikan Dasar dan Menengah', 'central', 'BPMP PROVINSI PAPUA', 'Pemeliharaan Pagar Kantor', 'Barang', 'Pengadaan Langsung', 'Papua, Jayapura (Kota)', 50000000, 'January 2026', 'APBN', 1, 1, '1 Paket', 'Melaksanakan pemeliharaan pagar kantor guna menjaga fungsi pengamanan, keselamatan, dan kerapian lingkungan kantor melalui kegiatan pemeriksaan kondisi pagar, pembersihan, perbaikan ringan, serta penggantian bagian pagar yang mengalami kerusakan agar pagar kantor tetap berfungsi dengan baik dan mendukung keamanan area kantor.', 'Pekerjaan pemeliharaan pagar kantor meliputi pemeriksaan kondisi pagar secara menyeluruh, pembersihan pagar dari karat, kotoran, dan lumut, perbaikan ringan pada bagian pagar yang rusak, bengkok, atau berkarat, pengelasan ulang sambungan yang lepas, serta pengecatan ulang pagar. Seluruh pekerjaan dilaksanakan sesuai ketentuan teknis dan standar keselamatan kerja yang berlaku agar pagar kantor tetap kuat, aman, dan tertata dengan baik.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 220398);
