INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123065', 62123065, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Sewa Komunikasi Metro Ethernet M2M', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 135000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 Bulan', 'BMKG saat ini mengoperasikan berbagai perangkat observasi otomatis yang tersebar di sejumlah wilayah Indonesia, antara lain Automatic Weather Station (AWS), Automatic Rain Gauge (ARG), Automatic Agroclimate Weather Station (AAWS), serta perangkat Accelerograph dan Intensity Meter. Perangkat-perangkat tersebut menghasilkan data observasi cuaca, curah hujan, agroklimat, serta parameter kebumian yang menjadi dasar penting dalam mendukung prakiraan cuaca, penyusunan informasi iklim nasional, dan kebutuhan pemantauan serta pencatatan kejadian/pergerakan tanah. Agar data observasi dapat dimanfaatkan secara optimal, pengiriman data dari seluruh titik pengamatan harus berlangsung otomatis, kontinu, dan real time menuju sistem penerimaan dan pengolahan data di BMKG. Untuk memenuhi kebutuhan tersebut, BMKG telah memanfaatkan sistem telekomunikasi berbasis layanan data seluler (packet data) untuk mengirimkan data observasi dari perangkat-perangkat lapangan ke pusat data BMKG. Namun, mengingat sebaran lokasi perangkat yang luas, variasi kondisi geografis, serta kebutuhan operasional 24x7, diperlukan media komunikasi yang lebih terkelola, stabil, dan mampu menjaga keberlangsungan pengiriman data secara konsisten. Oleh karena itu, sistem pengumpulan data AWS, ARG, AAWS, Accelerograph, dan Intensity Meter diselenggarakan melalui jalur komunikasi Metro Ethernet Machine-to-Machine (M2M) sebagai sarana konektivitas data, guna memastikan pengiriman data berjalan otomatis dan real time serta mendukung kelancaran operasional dan produktivitas BMKG.', 'Jalur Komunikasi Metro Ethernet M2M yang menghubungkan antara BMKG ke PT. Telekomunikasi Seluler Indonesia yang digunakan untuk saluran data M2M Telkomsel. Jalur Komunikasi Metro Ethernet M2M merupakan layanan konektivitas yang menghubungkan jaringan BMKG dengan jaringan inti (core) layanan data M2M berbasis seluler yang digunakan BMKG sebagai saluran pengiriman data perangkat lapangan. Layanan ini harus memiliki mutu dan kualitas yang andal untuk mendukung pengiriman data observasi secara otomatis, kontinu, dan real time, dengan tingkat ketersediaan layanan (availability) minimal sesuai ketentuan SLA BMKG. Jalur Metro Ethernet M2M wajib menyediakan kualitas transmisi yang stabil dan terkelola (latency dan jitter rendah serta packet loss minimal), mendukung kapasitas trafik rendah hingga menengah/tinggi serta memungkinkan peningkatan kapasitas bila diperlukan, dilengkapi mekanisme keamanan dan isolasi trafik (misalnya VLAN/VRF atau setara), serta didukung monitoring dan penanganan gangguan sesuai SLA agar kontinuitas layanan tetap terjaga.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 220891);
