INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123103', 62123103, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Renewal update lisensi Next Generation Firewall (NGFW)', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 1450000000, 'May 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Lisen', 'pembaruan lisensi (license renewal) firewall merupakan bagian integral dari strategi mitigasi risiko siber yang berkelanjutan. Lisensi yang aktif memastikan ketersediaan fitur-fitur keamanan canggih, seperti pencegahan serangan zero-day, analisis perilaku lalu lintas jaringan, dan integrasi dengan sistem pemantauan keamanan lainnya. Lebih dari itu, lisensi juga memberikan akses terhadap dukungan teknis 24/7, penggantian suku cadang secara cepat, pembaruan firmware dan perangkat lunak terbaru, serta dokumentasi resmi dari vendor. Keberlanjutan lisensi firewall bukan sekadar pemenuhan administratif, melainkan langkah profesional dan terukur dalam manajemen risiko keamanan jaringan. Dengan menjaga lisensi tetap aktif, BMKG memastikan sistem keamanan jaringan dapat berfungsi secara optimal dan adaptif terhadap dinamika ancaman siber, sekaligus menjaga keandalan layanan publik yang menjadi mandat utama lembaga.', 'Untuk menjamin ketersediaan layanan dan kelangsungan operasional perangkat keamanan jaringan, penyedia wajib menyediakan dukungan teknis dan layanan pemeliharaan dengan ketentuan minimum sebagai berikut: Penggantian Suku Cadang (Hardware Replacement) -Minimal Next Business Day (NBD): Penggantian suku cadang dilakukan dengan pengiriman pada hari kerja berikutnya sejak laporan diterima dan diverifikasi -Berlaku minimal selama 1 (satu) tahun sejak perangkat diterima dan diaktifkan., Dukungan Teknis via Telepon : -Konsultasi teknis melalui telepon selama 24 jam sehari, 7 hari seminggu (24x7) -Layanan ini berlaku minimal selama 1 tahun., Dukungan Teknis via Web (Online Support) : Akses ke kanal dukungan teknis melalui portal web selama 24x7, termasuk pelacakan tiket, dokumentasi teknis, dan forum dukungan. -Berlaku minimal selama 1 tahun. 4. Pembaruan Perangkat Lunak dan Firmware ○ Akses penuh terhadap pembaruan versi perangkat lunak (patch, feature update, firmware upgrade) yang dirilis oleh produsen resmi. ○ Berlaku minimal selama 1 tahun. 5. Akses Knowledge Base ○ Akses ke portal basis pengetahuan (knowledge base) resmi dari vendor, termasuk panduan konfigurasi, dokumentasi teknis, dan troubleshooting guide. ○ Berlaku minimal selama 1 tahun. 6. Service Level Agreement (SLA) – Respon dan Penyelesaian Insiden ○ Respon awal untuk insiden kritikal (high severity): maksimal 1 jam sejak laporan diterima. ○ Waktu penyelesaian: ■ Insiden sedang (medium severity): maksimal 8 jam kerja ■ Insiden ringan (minor severity): maksimal 24 jam kerja', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 220933);
