INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123076', 62123076, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Sewa komunikasi backup Kantor Pusat dan BBMKG', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 7680000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 BLN', 'Pemanfaatan jaringan komunikasi yang terintegrasi dan terkelola menjadi kebutuhan mendasar bagi BMKG sehingga dibutuhkan jalur backup atau cadangan karena fungsinya saat ini tidak hanya sebagai sarana konektivitas, tetapi juga sebagai tulang punggung operasional layanan data dan informasi. Jaringan komunikasi berperan penting dalam menjaga kesinambungan alur kerja mulai dari akuisisi data sensor, pengiriman data dari UPT maupun sensor MKKuG ke pusat pengolahan di BMKG Pusat, hingga diseminasi informasi dan peringatan dini kepada pemangku kepentingan dan masyarakat. Dalam konteks pelayanan kebencanaan, jaringan komunikasi memegang peranan signifikan pada proses diseminasi sistem peringatan dini seperti InaTEWS, InaMEWS, dan InaCEWS, yang menuntut kecepatan, keandalan, dan ketepatan waktu. Mengingat layanan BMKG bersifat kritikal dan beroperasi 24 jam sehari, 7 hari seminggu, maka jaringan komunikasi harus dipertahankan tetap aktif dan stabil tanpa henti. Konsekuensinya, setiap kegiatan perubahan konfigurasi, relokasi, upgrade perangkat, maupun modernisasi teknologi wajib direncanakan dengan pendekatan yang meminimalkan gangguan operasional. Prinsip yang digunakan adalah zero/minimal downtime melalui penerapan cutover window yang terukur, mekanisme rollback, serta penyediaan jalur komunikasi cadangan agar pelayanan tetap berjalan ketika terjadi perpindahan beban atau pemeliharaan.', 'Menyediakan sistem jaringan komunikasi yang optimal sebagai jalur komunikasi backup yang mampu menjamin kelangsungan pertukaran data dan informasi antara BMKG Pusat dan BBMKG Wilayah I–V dalam menunjang produktivitas dan operasional layanan BMKG yang berjalan 24/7. Sistem yang disediakan harus memiliki tingkat ketersediaan (availability) dan keandalan (reliability) yang tinggi untuk menjaga konektivitas tetap stabil, mendukung kebutuhan komunikasi data dari trafik rendah hingga tinggi, serta mampu melakukan failover ketika jalur utama mengalami gangguan agar layanan tetap beroperasi dengan downtime minimal. Selain itu, sistem wajib memenuhi aspek keamanan komunikasi untuk menjaga kerahasiaan (confidentiality) dan integritas (integrity) data melalui mekanisme pengamanan yang sesuai, termasuk pengaturan segmentasi dan kontrol akses sesuai kebijakan internal BMKG. Untuk memastikan mutu layanan, penyedia juga harus menyediakan monitoring status dan trafik secara real-time serta dukungan operasional agar kualitas layanan tetap terjaga selama masa implementasi maupun operasional berjalan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 220987);
