INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123112', 62123112, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Pemeliharaan Operasional MEWS', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 1200000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Lok', 'Tujuan dari pengadaan Suku Cadang MEWS Badan Meteorologi Klimatologi dan Geofisika adalah sebagai berikut: Terpeliharanya perangkat Sistem Wall Display/Backdrop MEWS dan Media Room secara berkala sebagai salah satu penunjang utama operasional meteorologi; Menjaga kontinuitas data dan informasi yang diinformasikan kepada publik; Mempermudah dan mempercepat informasi cuaca untuk masyarakat di seluruh wilayah Indonesia serta dapat meningkatkan penyebaran informasi cuaca ke masyarakat, Dapat mensosialisasikan tentang penyebaran produk informasi cuaca dan peringatan dini cuaca ekstrim BMKG kepada masyarakat, instansi dan pihak terkait.', 'Kegiatan pemeliharaan ini dilaksanakan dalam rangka menunjang operasional MEWS (Meteorology Early Warning System) kedeputian Bidang Meteorologi, dimana komponen dalam MEWS ini meliputi Sistem Wall Display/Backdrop MEWS dan Display Media Room untuk wawancara dengan Media TV. Perangkat Sistem Wall Display/Backdrop Ruang Operasional & Display MEWS BMKG (Badan Meteorologi Klimatologi dan Geofisika) terpasang di Ruang Operasional sedangkan Media Room terpasang di Media Room Kedeputian Meteorologi Lantai IV Gedung C BMKG sejak tahun 2012. Untuk menjaga kontinuitas operasionalnya, sistem MEWS ini perlu dilakukan pemeliharaan secara berkala.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 221134);
