INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63175168', 63175168, 'analyze_legacy', 'Kementerian Kelautan Dan Perikanan', 'central', 'STASIUN KARANTINA IKAN PENGENDALIAN MUTU DAN KEAMANAN HASIL PERIKANAN BANDUNG', 'Belanja Bahan', 'Barang', 'Pengadaan Langsung', 'Jawa Barat, Cimahi (Kota)', 5000000, 'April 2026', 'APBN - PNBP (D)', 1, 1, '1 Paket', '1. Biaya Pembelian Contoh Uji (12 Wilayah x 2 Periode) ( 2, PKT, @ 2500000 );', 'Lingkup Pekerjaan • Volume: 2 Paket (Mewakili Periode I dan Periode II). • Pagu Anggaran: Rp2.500.000,- per Paket (Total Rp5.000.000,-). • Distribusi Wilayah: Mencakup pengambilan/pembelian contoh uji di 12 Wilayah (sesuai daftar distribusi wilayah kerja instansi). • Tujuan: Mendapatkan sampel/contoh uji yang representatif dari pasar atau titik lokasi tertentu untuk dilakukan pengujian parameter kualitas di laboratorium. • Kriteria Sampel: o Sampel harus dalam kondisi asli, kemasan tidak rusak, dan belum melewati masa kedaluwarsa. o Pembelian dilakukan secara acak (random sampling) pada vendor/pedagang yang berbeda di setiap wilayah untuk menjaga objektivitas hasil uji. o Volume/Jumlah per sampel harus memenuhi kebutuhan minimal pengujian laboratorium (sesuai metode SNI atau standar uji yang berlaku). • Metode Pembelian: Pembelian dilakukan secara langsung di lapangan oleh petugas sampling yang ditunjuk. • Output / Keluaran Pekerjaan 1. Tersedianya contoh uji dari 12 wilayah yang siap untuk dilakukan pengujian. 2. Laporan Pembelian Contoh Uji yang dilampiri dengan: Nota/Kuitansi Pembelian asli dari pedagang/toko di masing-masing wilayah. Dokumentasi foto pengambilan/pembelian sampel di lokasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 221179);
