INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123090', 62123090, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Pemeliharaan Sibatik', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 200000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Lok', 'Tujuan dari pemeliharaan Sistem Informasi Bantuan TIK adalah untuk mencegah terjadinya kerusakan dan/atau mempertahankan keberlangsungan operasional Sistem Informasi Bantuan TIK secara terus menerus dan peningkatan SDM . Sasaran kegiatan Pemeliharaan Sistem Informasi Bantuan TIK adalah melakukan pemeliharaan Sibatik dan monitoring serta evaluasi perkembangan teknologi informasi. Output dari Pemeliharaan Peralatan Sistem Informasi Bantuan TIK adalah terpeliharanya Sistem Informasi Bantuan TIK BMKG. Outcome yaitu Sistem Informasi Bantuan TIK BMKG dapat beroperasional dengan baik sehingga layanan Direktorat Sistem Jaringan Komunikasi terpenuhi dengan efektif dan efisien kepada pihak pengguna.', 'Lingkup pekerjaan pemeliharaan Sistem Informasi Bantuan TIK meliputi: enhancement ITSM Module dan pemeliharan rutin. Rinciannya adalah sebagai berikut. a. Melakukan implementasi dan pendampingan ITSM dalam kegiatan operasional dengan menggunakan ITSM Tools ManageEngine Servicedesk Plus; b. Melakukan transfer knowledge kepada pengguna baik pada tingkat Technicians, Admin dan Users terkait ITSM. c. Kunjungan pemeliharaan rutin secara berkala yaitu sebanyak 2 kali kunjungan, setiap kunjungan terdiri dari 1 orang teknisi ahli selama 1 hari kerja dan 1 kali kunjungan dengan pendampingan Monev (Monitoring Evaluasi) 1 orang, untuk melakukan pemeliharaan dan perbaikan guna menjamin/memastikan bahwa tidak terjadi penurunan kinerja sistem yang berlokasi di BMKG Pusat Tujuan keseluruhan pemeliharaan rutin adalah untuk merawat peralatan, mencegah timbulnya masalah atau gangguan saat sistem beroperasi serta memastikan keberlangsungan operasional dari instrumen/ peralatan tersebut. Kegiatan pemeliharaan rutin terdiri dari: ● Pemeriksaan Module service request ● Pemeriksaan Module Service Level Agreement ● Pemeriksaan Module service catalog ● Pemeriksaan Module incident management ● Pemeriksaan Module Knowledge Management', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 221295);
