INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123108', 62123108, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Pemeliharaan Sistem Integrasi Radar Cuaca Mandiri', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 164000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 STM', 'Sistem Integrasi Data Radar Cuaca Mandiri (SIDARMA) merupakan sistem integrasi radar cuaca yang dibangun untuk mengakomodir kebutuhan prakirawan cuaca sebagai data dukung untuk membuat prakiraan cuaca dalam jangka waktu tertentu. Sistem ini menggabungkan seluruh sistem radar cuaca di BMKG yang saat ini telah memiliki 42 sistem radar. Sistem SIDARMA yang saat ini telah berjalan merupakan aplikasi berbasis web yang dapat di akses oleh user/prakirawan secara internal/eksternal. Beberapa produk radar cuaca telah tersedia dalam sistem ini seperti MAX, QPE1h, QPE24h, velocity dan rainrate. Pengembangan sistem secara multiplatform akan diperlukan pada tahapan berikutnya, sehingga perlu dipersiapkan perangkat penunjang operasional untuk mengakomodir hal tersebut. Dalam operasionalnya sistem ini tidak terlepas dari permasalahan teknis yang berpotensi terjadi, untuk itu diperlukan kegiatan pemeliharaan secara berkala untuk menjaga performa dari sistem. Salah satu komponen yang perlu untuk dikembangkan lebih lanjut adalah sistem Monitoring Data, status proses pembuatan produk dan jaringan komunikasi ke site radar. Selain itu sistem verifikasi data radar harian dan bulanan serta pembuatan dokumentasi detail sistem SIDARMA perlu dilakukan untuk menunjang kegiatan operasiona', 'Sistem Integrasi Data Radar Cuaca Mandiri (SIDARMA) merupakan sistem integrasi radar cuaca yang dibangun untuk mengakomodir kebutuhan prakirawan cuaca sebagai data dukung untuk membuat prakiraan cuaca dalam jangka waktu tertentu. Sistem ini menggabungkan seluruh sistem radar cuaca di BMKG yang saat ini telah memiliki 42 sistem radar. Sistem SIDARMA yang saat ini telah berjalan merupakan aplikasi berbasis web yang dapat di akses oleh user/prakirawan secara internal/eksternal. Beberapa produk radar cuaca telah tersedia dalam sistem ini seperti MAX, QPE1h, QPE24h, velocity dan rainrate. Pengembangan sistem secara multiplatform akan diperlukan pada tahapan berikutnya, sehingga perlu dipersiapkan perangkat penunjang operasional untuk mengakomodir hal tersebut. Dalam operasionalnya sistem ini tidak terlepas dari permasalahan teknis yang berpotensi terjadi, untuk itu diperlukan kegiatan pemeliharaan secara berkala untuk menjaga performa dari sistem. Salah satu komponen yang perlu untuk dikembangkan lebih lanjut adalah sistem Monitoring Data, status proses pembuatan produk dan jaringan komunikasi ke site radar. Selain itu sistem verifikasi data radar harian dan bulanan serta pembuatan dokumentasi detail sistem SIDARMA perlu dilakukan untuk menunjang kegiatan operasiona', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 221433);
