INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123062', 62123062, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Pemeliharaan Sistem Signature BMKG', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 200000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Sistem', 'Sistem Signature adalah suatu sistem atau alat untuk mempermudah prakirawan cuaca dalam melihat dan menginterpretasikan produk Numerical Weather Prediction (NWP) sebagai salah satu proses pengambilan keputusan dalam prediksi cuaca harian, tiga harian hingga mingguan serta menyediakan informasi berbasis dampak yang berasal dari cuaca yang signifikan guna mengurangi kurangnya kerugian materil maupun non materil. Untuk menjaga keberlangsungan operasional MEWS terlaksana dengan baik dan tidak ada hambatan selama 24 jam, maka sistem SIGNATURE BMKG dan sistem harus terpelihara secara baik. Tujuan utama dari kegiatan pemeliharaan sistem SIGNATURE BMKG adalah: 1. Terpeliharanya perangkat Sistem Signature beserta sistem pendukung operasional layanan Impact Based Forecast. 2. Menjaga Sustainability sistem SIGNATURE, terutama produk IBF dan produk pendukung lainnya agar bisa terdisplay dengan baik setiap hari. 3. Tercapainya Peningkatan dan Perbaikan terhadap sistem SIGNATURE', 'Pemeliharaan Sistem SIGNATURE BMKG tahun 2025 ini adalah: Sistem SIGNATURE BMKG dapat digunakan jika dibutuhkan, keluhan dan permasalahan dari tim pengguna (user) pada saat menggunakan kedua sistem tersebut proses tindak lanjut akan segera dilakukan untuk memperbaiki sistem, Adanya peningkatan dan perbaikan pada Sistem SIGNATURE BMKG sehingga menghasilkan produk yang diinginkan oleh pengguna (user) dan Perangkat lunak dalam status berlangganan dan dapat digunakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 221439);
