INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123094', 62123094, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Sewa komunikasi utama Kantor Pusat dan BBMKG', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 9193908000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '12 BLN', 'Pemanfaatan jaringan komunikasi merupakan kebutuhan yang beralasan dan strategis karena pada saat ini penggunaannya sangat membantu dan menjadi tulang punggung dalam kegiatan operasional BMKG, khususnya dalam menjamin kontinuitas pelayanan data dan informasi meteorologi, klimatologi, dan geofisika. Jaringan komunikasi memegang peranan yang sangat signifikan dalam kegiatan diseminasi sistem peringatan dini nasional, antara lain InaTEWS (Indonesia Tsunami Early Warning System), InaMEWS, dan InaCEWS, yang menuntut kecepatan, keakuratan, dan keandalan tinggi dalam pengiriman data dan informasi kepada pemangku kepentingan serta masyarakat. Mengingat peran jaringan komunikasi yang sangat krusial dalam mendukung kegiatan operasional BMKG, maka jaringan komunikasi harus dapat dipertahankan beroperasi selama 24 jam sehari dan 7 hari seminggu secara berkelanjutan. Setiap perubahan, pengembangan, maupun peningkatan teknologi jaringan yang dilakukan harus dirancang sedemikian rupa agar tidak menimbulkan gangguan layanan (zero downtime), sehingga proses pengumpulan, pengolahan, dan diseminasi data tetap berjalan tanpa hambatan. Dengan demikian, BMKG dapat memperoleh sistem jaringan komunikasi yang lebih andal, stabil, dan reliabel, serta tetap mempertimbangkan efisiensi biaya (cost efficiency). Pemanfaatan sistem jaringan komunikasi yang optimal merupakan solusi strategis dalam membangun konektivitas yang terintegrasi antara BMKG Pusat dengan Kantor Balai Besar Wilayah BMKG serta unit-unit kerja terkait lainnya. Sistem jaringan yang dibangun diharapkan mampu memenuhi aspek keamanan dan kualitas layanan yang mencakup tingkat ketersediaan (availability), kerahasiaan data (confidentiality), dan keutuhan data (integrity) yang lebih baik, sehingga mendukung kelancaran operasional BMKG secara nasional serta peningkatan kualitas pelayanan informasi kepada masyarakat dan pemangku kepentingan.', 'Sewa Internet Internasional 800 Mbps untuk Jakarta Internet IX (IP Transit) Sewa Link Utama Metro-E layer 2 Fiber Optik 1000 Mbps BMKG Pusat Sewa Internet Internasional Dedicated Fiber Optik 1.5 Gbps untuk perkantoran lokasi BMKG Pusat Jakarta Sewa Internet Internasional Dedicated Fiber Optik 60Mbps BBMKG Wilayah I Medan Sewa Internet Internasional Dedicated Fiber Optik 60Mbps BBMKG Wilayah II Ciputat Sewa Internet Internasional Dedicated Fiber Optik 100 Mbps BBMKG Wilayah III Denpasar Sewa Internet Internasional Dedicated Fiber Optik 60Mbps BBMKG Wilayah IV Makassar Sewa Internet Internasional Dedicated Fiber Optik 60Mbps BBMKG Wilayah V Jayapura Sewa Internet Internasional Dedicated Fiber Optik 60 Mbps untuk Rumah Dinas Kepala BMKG di Pondok Betung, Tangerang Selatan Sewa Internet Internasional Dedicated Fiber Optik 10 Mbps untuk GSG Citeko Sewa Internet Internasional Dedicated Fiber Optik 60 Mbps Kedeputian Bidang Modifikasi Cuaca (Gedung Ex-STMKG)', 438000000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 221450);
