INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123083', 62123083, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Suku Cadang Pendukung Multimedia', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 200000000, 'May 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Lok', 'Direktorat Sistem Jaringan Komunikasi mengelola infrastruktur server krusial yang menopang berbagai layanan digital BMKG, termasuk InfoBMKG, aplikasi SIBATIK (Sistem Bantuan Telekomunikasi, Instrumentasi, dan Komputasi), serta website diseminasi UPT (Unit Pelaksana Teknis) dan Pusat. Keandalan dan kinerja optimal dari infrastruktur ini adalah prasyarat untuk menjamin ketersediaan layanan digital secara kontinu. Namun, seiring berjalannya waktu, analisis operasional menunjukkan adanya peningkatan risiko signifikan yang mengancam keberlanjutan layanan akibat degradasi perangkat keras yang tak terhindarkan. Evaluasi terkini mengidentifikasi beberapa tantangan krusial yang berakar pada siklus hidup (life cycle) perangkat. Sebagian besar komponen server yang beroperasi saat ini telah melampaui masa garansi resminya. Konsekuensinya, setiap kerusakan tidak lagi ditanggung oleh pabrikan, sehingga proses perbaikan atau penggantian menjadi tanggung jawab penuh direktorat dan dapat berpotensi pada terhambatnya layanan.', 'Pengadaan ini ditujukan agar tersedianya suku cadang sesuai spesifikasi teknis dapat memastikan keberlangsungan operasional, menjaga keandalan sistem, serta mendukung stabilitas kinerja peralatan secara menyeluruh. Dengan adanya ketersediaan suku cadang yang memadai, setiap potensi keterlambatan atau hambatan yang timbul akibat ketidaktersediaan komponen dapat diminimalisir, sehingga kesinambungan layanan Teknologi Informasi dapat terjaga dengan baik. Suku cadang yang diadakan wajib memenuhi standar kualitas dan kompatibilitas dengan perangkat utama, serta memiliki keandalan yang dapat dipertanggungjawabkan sesuai dengan ketentuan teknis yang berlaku. Pengadaan ini sekaligus merupakan langkah strategis dalam memastikan kesiapan infrastruktur, mendukung efisiensi pengelolaan aset, serta memberikan jaminan terhadap kontinuitas layanan yang bergantung pada peralatan Teknologi Informasi. Dengan demikian, suku cadang yang diadakan tidak hanya berfungsi sebagai material pendukung, tetapi juga sebagai bagian penting dari strategi penguatan sistem dan jaminan keberlangsungan operasional organisasi secara keseluruhan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 221517);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123070', 62123070, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Pemeliharaan Sistem Satelit Cuaca', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 190000000, 'January 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 sistem', 'Guna mendukung kegiatan Peringatan Dini Cuaca Ekstrem atau Meteorology Early Warning System (MEWS) BMKG, diperlukan sebuah sistem terpadu yang mampu mengolah data dari Satelit Himawari. 2Satelit ini memiliki resolusi spasial dan temporal yang tinggi, sehingga pengolahannya harus dilakukan secara cepat, tepat, dan akurat. Pada tahun 2015, BMKG telah melakukan pengadaan server pemrosesan data Himawari-9 yang datanya diperoleh dari cloud server Japan Meteorological Agency (JMA) melalui internet. 4Sistem yang dikenal sebagai Sistem Satelit Cuaca ini terpasang di Gedung A, Kantor BMKG Pusat, Jakarta. 5Sistem ini menghasilkan berbagai produk unggulan seperti GeoHotspot, RGB Debu Vulkanik, Sebaran Asap, dan Citra Inframerah. Untuk menjaga keberlangsungan operasional MEWS Meteorologi, kegiatan pemeliharaan terhadap Sistem Satelit Cuaca, termasuk di dalamnya sistem HimawariCast, menjadi sangat penting. 7Pemeliharaan ini bertujuan untuk memastikan seluruh perangkat keras dan perangkat lunak berfungsi dengan baik, sehingga penyampaian informasi cuaca dan peringatan dini kepada masyarakat serta stakeholder terkait dapatrjalan lancar tanpa kendala.', 'Pemeliharaan mencakup seluruh perangkat keras yang ada dalam Sistem Satelit Cuaca, yaitu: Server Processing Utama (DELL): Pemeriksaan dan perawatan rutin untuk memastikan operasional 24/7. Server Blade Backup (Supermicro): Pemeriksaan dan pengujia \\fungsionalitas sebagai sistem cadangan. Network Attached Storage (NAS QNAP): Pemeliharaan untumemastikan data tersimpan dengan aman dan dapat diaksSuku Cadang (Spare Parts): Penyediaan dan penggantian komponen perangkat keras yang mengalami kerusakan, seperti hard drive, RAM, atau power supply, yang harus kompatibel dengan sistem yang ada.Perangkat Jaringan: Pemeriksaan dan konfigurasi perangkat seperti witch dan router untuk menjamin konektivitas antar sistem.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 221518);
