INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123055', 62123055, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Suku Cadang Website Meteorologi Penerbangan', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 113049000, 'June 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 SET', 'Keselamatan penerbangan berkaitan erat dengan kondisi cuaca. Oleh karenanya kecepatan, ketepatan dan keakuratan dalam mendiseminasikan informasi cuaca menjadi hal yang sangat penting. BMKG mempunyai peranan penting dalam mendiseminasikan informasi cuaca penerbangan melalui berbagai kanal informasi termasuk website, oleh karena itu dibutuhkan sistem yang dapat membantu memudahkan SDM dalam mempercepat pekerjaan sehari-hari. Untuk itu diperlukan Suku Cadang Website Meteorologi Penerbangan diharapkan dapat membantu memudahkan dan mempercepat pekerjaan pegawai BMKG di pusat dan di daerah dalam membuat, mengoreksi, dan mendiseminasikan informasi cuaca penerbangan baik ke stasiun, operator penerbangan maupun masyarakat umum.', 'Suku Cadang Pemeliharaan Website Meteorologi Penerbangan tahun 2026 akan mengganti komponen perangkat keras existing untuk mendukung kinerja pengembangan website meteorologi penerbangan dan monitoring operasional server dan sistem website meteorologi penerbangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 221673);
