INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123072', 62123072, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Pemeliharaan Website dan Aplikasi Direktorat  Sistem Jaringan Komunikasi', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 200000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 lok', 'Kegiatan pemeliharaan ini sangat penting untuk : Keandalan dan ketersediaan : pemeliharaan rutin memastikan website dan aplikasi selalu aktif dan dapat diakses dengan cepat kapanpun dibutuhkan, terutama saat terjadi bencana. Kegagalan sistem saat krisis dapat berakibat fatal dan Keamanan Data Publik: pembaruan keamanan (patching) dan audit siber secara berkala melindungi sistem dari serangan peretas (hacker), menjaga integritas data MKG, dan mencegah penyebaran, informasi palsu yang berbahaya dan Konsistensi Informasi: pemeliharaan memastikan seluruh fitur, tautan, dan data yang ditampilkan (baik di portal pusat maupun UPT) berfungsi dengan benar dan konsisten, sehingga masyarakat menerima informasi yang akurat dan utuh.', 'Pemeliharaan Website dan Aplikasi Direktorat Sistem Jaringan Komunikasi dilakukan dengan cara sebagai berikut: Melakukan real time monitoring terhadap website dan aplikasi, pemeliharaan preventif terhadap website dan aplikasi, serta pemeliharaan korektif terhadap website dan aplikasi, Melakukan assessment awal atas objek pemeliharaan dalam pekerjaan ini, Melakukan perencanaan dan tindak lanjut perencanaan untuk pekerjaan ini, Menyediakan dukungan teknis yang standby 24/7, untuk menerima notifikasi peringatan dari aplikasi monitoring dan menindaklanjutinya sesuai dengan level severity nya, Penyedia didampingi minimal 1 (satu) orang petugas dari Direktorat Sistem Jaringan Komunikasi melakukan kunjungan ke Kantor Pusat BMKG dan DCI - Cibitung minimal satu bulan satu kali untuk melaksanakan pemeliharaan perangkat website dan aplikasi BMKG, dan Pelaporan : Membuat rangkuman laporan SLA pada setiap akhir bulan, yang disajikan dalam bentuk executive summary serta Membuat laporan bulanan kegiatan pemeliharaan preventif dan laporan pemeliharaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 221678);
