INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123092', 62123092, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Suku Cadang Teknologi Komunikasi', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 200000000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '2 Lok', 'Direktorat Sistem Jaringan Komunikasi mengelola infrastruktur server krusial yang menopang berbagai layanan digital BMKG, termasuk InfoBMKG, aplikasi SIBATIK (Sistem Bantuan Telekomunikasi, Instrumentasi, dan Komputasi), serta website diseminasi UPT (Unit Pelaksana Teknis) dan Pusat. Keandalan dan kinerja optimal dari infrastruktur ini adalah prasyarat untuk menjamin ketersediaan layanan digital secara kontinu. Namun, seiring berjalannya waktu, analisis operasional menunjukkan adanya peningkatan risiko signifikan yang mengancam keberlanjutan layanan akibat degradasi perangkat keras yang tak terhindarkan. Evaluasi terkini mengidentifikasi beberapa tantangan krusial yang berakar pada siklus hidup (life cycle) perangkat. Sebagian besar komponen server yang beroperasi saat ini telah melampaui masa garansi resminya. Konsekuensinya, setiap kerusakan tidak lagi ditanggung oleh pabrikan, sehingga proses perbaikan atau penggantian menjadi tanggung jawab penuh direktorat dan dapat berpotensi pada terhambatnya layanan.', 'Direktorat Sistem Jaringan Komunikasi mengelola infrastruktur server krusial yang menopang berbagai layanan digital BMKG, termasuk InfoBMKG, aplikasi SIBATIK (Sistem Bantuan Telekomunikasi, Instrumentasi, dan Komputasi), serta website diseminasi UPT (Unit Pelaksana Teknis) dan Pusat. Keandalan dan kinerja optimal dari infrastruktur ini adalah prasyarat untuk menjamin ketersediaan layanan digital secara kontinu. Namun, seiring berjalannya waktu, analisis operasional menunjukkan adanya peningkatan risiko signifikan yang mengancam keberlanjutan layanan akibat degradasi perangkat keras yang tak terhindarkan. Evaluasi terkini mengidentifikasi beberapa tantangan krusial yang berakar pada siklus hidup (life cycle) perangkat. Sebagian besar komponen server yang beroperasi saat ini telah melampaui masa garansi resminya. Konsekuensinya, setiap kerusakan tidak lagi ditanggung oleh pabrikan, sehingga proses perbaikan atau penggantian menjadi tanggung jawab penuh direktorat dan dapat berpotensi pada terhambatnya layanan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 221874);
