INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62897590', 62897590, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Pengadaan Mobil Pembayaran Pajak Keliling', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 835525860, 'January 2026', 'APBD', 1, 1, '2 unit', 'Uraian pekerjaan Pengadaan Mobil Pembayaran Pajak Keliling ini meliputi kegiatan pengadaan, penyediaan, pengiriman, dan penyerahan kendaraan operasional yang difungsikan sebagai mobil layanan pembayaran pajak keliling guna mendekatkan pelayanan kepada masyarakat, meningkatkan kemudahan akses pembayaran pajak daerah, serta mendukung optimalisasi penerimaan pajak daerah. Pekerjaan ini mencakup penyediaan kendaraan bermotor roda empat yang telah dimodifikasi atau dikonfigurasi khusus untuk pelayanan publik, dilengkapi dengan sarana pendukung transaksi pembayaran pajak, sistem informasi, dan perlengkapan layanan administrasi. Kendaraan yang disediakan harus dalam kondisi baru, laik jalan, dan memenuhi ketentuan peraturan perundang-undangan yang berlaku', 'Spesifikasi Teknis Pengadaan Mobil Pembayaran Pajak Keliling 1. Nama Pekerjaan Pengadaan Mobil Pembayaran Pajak Keliling 2. Jenis Kendaraan Kendaraan bermotor roda empat Setir kanan Kendaraan operasional pelayanan publik 3. Kondisi Kendaraan Baru (brand new) Bukan kendaraan bekas atau rekondisi Tahun produksi minimal tahun berjalan 4. Mesin Jenis bahan bakar: Bensin atau Diesel Sistem pembakaran: Injeksi Jumlah silinder: Minimal 4 silinder Kapasitas mesin: Minimal 1.300 cc Pendingin mesin: Air radiator 5. Sistem Transmisi Manual atau otomatis Jumlah percepatan sesuai standar pabrikan 6. Sistem Penggerak 2WD 7. Dimensi Kendaraan Panjang keseluruhan : ± 3.700 – 4.500 mm Lebar keseluruhan : ± 1.500 – 1.850 mm Tinggi keseluruhan : ± 1.700 – 2.500 mm 8. Kapasitas Penumpang Minimal 2–3 orang (sebelum modifikasi) Sebagian ruang disesuaikan untuk area pelayanan pajak 9. Modifikasi & Konfigurasi Layanan Kendaraan dikonfigurasi sebagai mobil layanan pembayaran pajak keliling, meliputi: Meja pelayanan/transaksi Kursi petugas 10. Perlengkapan Pelayanan Pajak Meja dan kursi pelayanan Stop kontak dan sistem kelistrikan tambahan Lampu interior tambahan Pendingin ruangan (AC) berfungsi optimal 11. Perlengkapan Teknologi Informasi (opsional sesuai kebutuhan) UPS atau inverter listrik 12. Sistem Kelistrikan Aki standar pabrikan Sistem kelistrikan tambahan untuk perangkat pelayanan Pengaman listrik (MCB/sekring tambahan) 13. Fitur Keselamatan Sabuk pengaman Sistem rem standar pabrikan Lampu utama, sein, rem, dan hazard Alat pemadam api ringan (APAR) 14. Interior Dashboard standar pabrikan Pelapis interior rapi dan aman Tata letak ergonomis untuk pelayanan publik 15. Eksterior Warna kendaraan menyesuaikan Dilengkapi identitas/logo pemerintah daerah Stiker atau branding “Mobil Pelayanan Pembayaran Pajak Keliling” 16. Ban dan Velg Ban standar pabrikan Dilengkapi 1 (satu) ban serep 17. Kelengkapan Kendaraan Buku pemilik dan buku servis Kunci utama dan cadangan Dongkrak dan kunci roda Segitiga pengaman 18. Legalitas Kendaraan Dilengkapi STNK, TNKB, dan BPKB Atas nama instansi pemerintah sesuai peraturan perundang-undangan 19. Garansi Garansi kendaraan minimal 3 tahun atau 100.000 km Garansi hasil modifikasi dan perlengkapan layanan minimal 1 tahun 20. Pengiriman dan Serah Terima Kendaraan diserahkan dalam kondisi siap operasional Dilakukan pemeriksaan fisik dan uji fungsi kendaraan serta sarana pelayanan Serah terima dituangkan dalam Berita Acara Serah Terima (BAST)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 221881);
