INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62123059', 62123059, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Pemeliharaan Sistem Switching Data Operasional BMKG', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 200000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Lok', 'Kegiatan pemeliharaan ini dilaksanakan dalam rangka menunjang operasional pengumpulan dan penyebaran data dalam lingkup nasional dan internasional melalui Global Telecommunication System (GTS). Sistem InaGTS merupakan gerbang utama pertukaran data BMKG dengan simpul-simpul GTS di seluruh dunia, yang menuntut keandalan operasional 24/7 tanpa henti. Mengingat peranannya yang sangat kritis, diperlukan upaya pemeliharaan (maintenance) secara berkala dan profesional untuk menjaga kontinuitas operasionalnya, mencegah terjadinya kegagalan sistem (failure), dan memastikan performa sistem tetap optimal. Kegiatan pemeliharaan ini mencakup dukungan teknis, pemeliharaan perangkat keras dan perangkat lunak, serta pembaruan keamanan yang diperlukan.', 'Kegiatan ini meliputi : Melakukan perbaikan dan penggantian sparepart (bila diperlukan) dari dari seluruh unit perangkat sistem pada saat terjadi gangguan atau kerusakan pada sistem tersebut yang menyebabkan tidak operasional INAGTS dengan baik. Memulihkan kondisi tidak normal/ kerusakan sejak dini dari dari seluruh unit perangkat sistem INAGTS. Melakukan perbaikan program perangkat lunak sistem INAGTS berupa reinstalasi dan konfigurasi sistem; Melakukan perbaikan sistem atau melakukan instalasi ulang program berkaitan dengan System Administration; Melakukan perbaikan sistem atau melakukan instalasi ulang program berkaitan dengan Web Administration; Melakukan perbaikan sistem atau melakukan instalasi ulang program berkaitan dengan Database Administration.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 221885);
