INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62898338', 62898338, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Pengadaan Scanner Document', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 19300000, 'January 2026', 'APBD', 1, 1, '1 Unit', 'Pengadaan Scanner Dokumen A3 Uraian pekerjaan Pengadaan Scanner Dokumen A3 ini meliputi kegiatan pengadaan, penyediaan, pengiriman, dan penyerahan perangkat pemindai (scanner) dokumen berukuran hingga A3 yang digunakan untuk mendukung kegiatan digitalisasi arsip, pemindaian dokumen administrasi, peta, gambar teknis, dan dokumen resmi lainnya pada perangkat daerah. Pekerjaan ini mencakup penyediaan scanner dokumen A3 dengan kualitas pemindaian tinggi, kecepatan yang memadai, dan kemampuan pemindaian yang stabil untuk penggunaan rutin maupun volume kerja tinggi. Perangkat yang disediakan harus dalam kondisi baru, bukan bekas atau rekondisi, serta kompatibel dengan sistem dan aplikasi pengelolaan dokumen yang digunakan. Ruang lingkup pekerjaan meliputi: Pengadaan scanner dokumen dengan kemampuan pemindaian ukuran hingga A3 sesuai jumlah dan spesifikasi teknis yang ditetapkan. Menjamin perangkat scanner dalam kondisi baru, asli pabrikan, dan belum pernah digunakan. Penyediaan perangkat scanner lengkap beserta aksesori standar pabrikan dan perangkat lunak pendukung. Menjamin hasil pemindaian dokumen yang jelas, tajam, dan akurat, termasuk untuk dokumen berukuran besar. Pengiriman dan penyerahan perangkat ke lokasi yang ditentukan oleh Pejabat Pembuat Komitmen (PPK) atau Pejabat Pengadaan dalam kondisi siap digunakan. Pelaksanaan instalasi awal, pengujian fungsi dasar, dan konfigurasi perangkat sesuai kebutuhan pengguna. Penggantian perangkat apabila ditemukan kerusakan, cacat produksi, atau ketidaksesuaian spesifikasi pada saat pemeriksaan. Pelaksanaan pemeriksaan dan serah terima barang yang dituangkan dalam Berita Acara Serah Terima (BAST) sesuai ketentuan yang berlaku. Dengan terlaksananya pekerjaan ini, diharapkan ketersediaan scanner dokumen A3 dapat mendukung percepatan digitalisasi arsip, peningkatan efisiensi pengelolaan dokumen, serta mendukung transformasi layanan administrasi berbasis elektronik secara efektif dan efisien.', 'Spesifikasi Teknis Scanner Dokumen A3 1. Nama Barang Scanner Dokumen A3 2. Jenis Scanner dokumen flatbed atau flatbed + ADF Mampu melakukan pemindaian dokumen berukuran hingga A3 3. Kondisi Baru (brand new) Bukan bekas atau rekondisi Produk resmi pabrikan 4. Ukuran Dokumen Maksimal Maksimal A3 (297 x 420 mm) 5. Resolusi Pemindaian Resolusi optik minimal 600 x 600 dpi Resolusi interpolasi minimal 1.200 dpi atau setara 6. Kecepatan Pemindaian Kecepatan pemindaian warna/hitam putih minimal 10 detik per halaman A3 (flatbed) Untuk ADF (jika ada): minimal 10–20 ppm ukuran A4 7. Kedalaman Warna Input: Minimal 48-bit color Output: Minimal 24-bit color 8. Sumber Cahaya LED (hemat energi dan tahan lama) 9. Fitur Pemindaian Scan warna, grayscale, dan hitam putih Auto crop Deskew Multi-page PDF OCR (Optical Character Recognition) support 10. Media yang Didukung Kertas HVS Dokumen arsip Foto Gambar teknik/peta tipis 11. Antarmuka / Konektivitas USB minimal USB 2.0 atau lebih tinggi Driver kompatibel dengan sistem operasi terbaru 12. Sistem Operasi yang Didukung Windows 10 / Windows 11 macOS (jika diperlukan) 13. Perangkat Lunak Software scanning bawaan pabrikan Mendukung penyimpanan ke PDF, JPEG, TIFF 14. Konsumsi Daya Tegangan: 220–240 V Konsumsi daya rendah (energy saving) 15. Dimensi dan Berat Dimensi sesuai standar scanner A3 Mudah ditempatkan di meja kerja 16. Kelengkapan Kabel data Kabel daya Adapter (jika terpisah) Buku petunjuk/manual CD/USB driver atau unduhan resmi 17. Keamanan dan Standar Memenuhi standar keselamatan listrik Sertifikasi produk resmi 18. Garansi Garansi resmi pabrikan minimal 1 (satu) tahun Layanan servis dan suku cadang tersedia 19. Pengiriman dan Serah Terima Unit dikirim dalam kondisi baik dan siap pakai Dilakukan uji fungsi pemindaian Serah terima dituangkan dalam Berita Acara Serah Terima (BAST)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 222296);
