INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62898053', 62898053, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Meja Kerja', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 12210000, 'January 2026', 'APBD', 1, 1, '2 unit', 'Belanja Meja Kerja untuk kelengkapan mobil pembayaran pajak keliling', '-Spesifikasi Teknis Belanja Meja Kerja untuk Mobil Pembayaran Pajak Keliling 1. Nama Barang Meja Kerja Mobil Pembayaran Pajak Keliling 2. Fungsi Sebagai sarana pendukung pelayanan administrasi dan transaksi pembayaran pajak keliling di dalam kendaraan (minibus), digunakan untuk penempatan perangkat kerja seperti laptop/PC, printer, dokumen, dan perlengkapan administrasi lainnya. 3. Jenis Meja kerja custom / portable Dirancang khusus untuk penggunaan di dalam kendaraan operasional Dapat dilipat atau bersifat tetap (fixed) sesuai kebutuhan ruang kendaraan 4. Dimensi Panjang: ± 100 – 120 cm Lebar: ± 45 – 60 cm Tinggi: ± 70 – 75 cm (Disesuaikan dengan dimensi interior mobil pembayaran pajak keliling) 5. Bahan Rangka: Besi hollow / aluminium anti karat Permukaan meja: Multipleks/plywood berlapis HPL atau bahan setara Tepi meja: Lis pelindung untuk keamanan 6. Konstruksi Kuat, stabil, dan tidak mudah bergeser Dilengkapi sistem pengunci/bracket ke bodi kendaraan Tahan terhadap getaran saat kendaraan berjalan 7. Warna dan Finishing Warna netral (abu-abu, putih, cokelat, atau menyesuaikan interior kendaraan) Finishing rapi, halus, dan tidak tajam 8. Fitur Pendukung Lubang manajemen kabel (cable management) Stopper/pembatas agar perangkat tidak mudah bergeser Laci atau rak penyimpanan (opsional) 9. Keamanan Sudut meja tumpul Material aman dan tidak mudah pecah Tidak mengganggu pergerakan petugas di dalam kendaraan 10. Kondisi Barang Baru Tidak cacat produksi Siap digunakan 11. Jumlah Sesuai kebutuhan dan tercantum dalam kontrak atau surat pesanan 12. Pengadaan dan Pemasangan Termasuk pengadaan, pengiriman, dan pemasangan di dalam kendaraan Pemasangan dilakukan rapi dan tidak merusak interior kendaraan 13. Pemeriksaan dan Serah Terima Dilakukan pemeriksaan fisik dan uji fungsi Barang yang tidak sesuai spesifikasi wajib diganti Serah terima dituangkan dalam Berita Acara Serah Terima (BAST) 14. Garansi Garansi produk dan pemasangan minimal 6–12 bulan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 222535);
