INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62897831', 62897831, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Pengadaan Mobil Pick Up', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 212608000, 'March 2026', 'APBD', 1, 1, '1 unit', 'Uraian pekerjaan Belanja Pengadaan Mobil Pick Up ini meliputi kegiatan pengadaan, penyediaan, pengiriman, dan penyerahan kendaraan bermotor roda empat jenis mobil pick up yang digunakan untuk mendukung kelancaran kegiatan operasional, distribusi barang, pengangkutan perlengkapan kerja, serta menunjang tugas lapangan pada perangkat daerah. Pekerjaan ini mencakup penyediaan mobil pick up yang memenuhi spesifikasi teknis, memiliki performa andal, efisien dalam penggunaan bahan bakar, serta sesuai untuk penggunaan operasional harian dan kondisi lapangan. Kendaraan yang disediakan harus dalam kondisi baru, bukan bekas atau rekondisi, dan telah memenuhi ketentuan peraturan perundang-undangan yang berlaku', '-Spesifikasi Teknis Mobil Pick Up 1. Nama Barang Mobil Pick Up 2. Jenis Kendaraan Kendaraan Bermotor Roda Empat Kendaraan operasional angkut barang 3. Kondisi Baru (brand new) Bukan kendaraan bekas atau rekondisi Tahun produksi minimal tahun berjalan 4. Tipe Kendaraan Pick up single cabin Setir kanan 5. Mesin Jenis mesin: Bensin atau Diesel Sistem pembakaran: Injeksi Jumlah silinder: Minimal 4 silinder Kapasitas mesin: Minimal 1.200 cc (bensin) atau setara Pendingin mesin: Air radiator 6. Sistem Transmisi Manual Jumlah percepatan: Minimal 5 percepatan maju + 1 mundur 7. Sistem Penggerak 2WD (Rear Wheel Drive) 8. Dimensi Bak Panjang bak minimal: ± 2.300 mm Lebar bak minimal: ± 1.600 mm Tinggi bak minimal: ± 300–400 mm Bak terbuka (open deck) 9. Kapasitas Angkut Minimal 800 kg Cocok untuk distribusi dan operasional lapangan 10. Sistem Rem Rem depan: Cakram Rem belakang: Drum Dilengkapi rem parkir 11. Sistem Kemudi & Suspensi Sistem kemudi: Power steering Suspensi depan: Independent / McPherson strut atau setara Suspensi belakang: Per daun (leaf spring) 12. Ban dan Velg Ukuran ban standar pabrikan Ban tubeless atau tube type Dilengkapi 1 (satu) ban serep 13. Fitur Keselamatan Sabuk pengaman pengemudi dan penumpang Lampu utama, lampu sein, lampu rem sesuai standar Spion kanan dan kiri 14. Interior Jumlah tempat duduk: 2–3 orang Dashboard standar pabrikan AC (opsional, menyesuaikan kebutuhan) 15. Eksterior Warna standar (putih/hitam/silver atau sesuai kebutuhan instansi) Dilengkapi bumper depan dan belakang Bak dilengkapi pengunci standar 16. Bahan Bakar Menggunakan BBM bersubsidi atau non-subsidi sesuai ketentuan Tangki bahan bakar minimal 40 liter 17. Kelengkapan Kendaraan Buku pemilik dan buku servis Kunci utama dan cadangan Dongkrak dan kunci roda Segitiga pengaman Ban serep 18. Legalitas Kendaraan Dilengkapi STNK, TNKB, dan BPKB Atas nama instansi pemerintah sesuai peraturan 19. Garansi Garansi kendaraan minimal 3 tahun atau 100.000 km (mana tercapai lebih dahulu) Garansi servis sesuai ketentuan pabrikan 20. Pengiriman dan Serah Terima Kendaraan dikirim dalam kondisi siap pakai Dilakukan pemeriksaan fisik dan uji fungsi Serah terima dituangkan dalam Berita Acara Serah Terima (BAST)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 223612);
