INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62898479', 62898479, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Pengadaan Standing Banner - Pengendalian', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 28900000, 'January 2026', 'APBD', 1, 1, '100 Buah', 'Uraian pekerjaan ini meliputi kegiatan pengadaan dan penyediaan standing banner sebagai media informasi, sosialisasi, publikasi, dan pendukung kegiatan promosi atau penyampaian informasi kepada masyarakat dan/atau pemangku kepentingan terkait program dan kegiatan instansi. Standing banner yang diadakan harus memiliki kualitas bahan dan cetak yang baik, desain informatif, serta konstruksi yang kokoh agar dapat digunakan secara efektif baik di dalam maupun di luar ruangan. Ruang Lingkup Pekerjaan meliputi: Perencanaan dan Persiapan Koordinasi dengan Pejabat Pembuat Komitmen (PPK) terkait konsep, desain, dan kebutuhan standing banner. Penyesuaian konten dan pesan sesuai tujuan kegiatan. Penyusunan Desain Pembuatan desain grafis standing banner yang informatif, komunikatif, dan menarik. Penyesuaian ukuran, tata letak, warna, dan elemen visual. Revisi desain hingga memperoleh persetujuan dari PPK. Pencetakan Standing Banner Pencetakan banner sesuai ukuran dan spesifikasi teknis. Menggunakan bahan cetak yang kuat dan warna yang jelas. Penyediaan Rangka/Stand Penyediaan rangka atau stand standing banner yang kokoh dan mudah dipasang. Rangka dapat digunakan ulang (reusable). Pengemasan dan Pengiriman Pengemasan standing banner dan rangka secara aman. Pengiriman ke lokasi yang ditentukan. Pengendalian Mutu Pemeriksaan kualitas bahan, hasil cetak, dan rangka. Penggantian apabila terdapat cacat atau ketidaksesuaian dengan spesifikasi. Serah Terima Pekerjaan Serah terima standing banner yang dituangkan dalam Berita Acara Serah Terima (BAST). Dengan terlaksananya pengadaan standing banner ini, diharapkan media informasi yang disediakan dapat digunakan secara optimal dalam mendukung kegiatan sosialisasi dan publikasi instansi.', 'Pengadaan Standing Banner 1. Nama Pekerjaan Pengadaan Standing Banner 2. Jenis Pekerjaan Pengadaan Barang Media Informasi dan Publikasi 3. Fungsi Sebagai media informasi, sosialisasi, dan publikasi kegiatan/program instansi pemerintah. 4. Spesifikasi Teknis Produk 4.1 Ukuran Ukuran standar: 60 × 160 cm atau 80 × 180 cm Ukuran lain dapat disesuaikan dengan kebutuhan dan persetujuan PPK 4.2 Bahan Banner Bahan Flexi China / Flexi Korea / Albatros atau setara Ketebalan minimal 280–340 gsm Tahan sobek dan tidak mudah luntur 4.3 Pencetakan Cetak full color (CMYK) Resolusi cetak tinggi Warna tajam dan jelas Hasil cetak tidak buram atau pecah 4.4 Finishing Potong rapi sesuai ukuran Pemasangan pada rangka/stand dengan baik Tanpa cacat cetak atau kerutan 5. Spesifikasi Rangka/Stand Jenis: X-Banner Bahan rangka: aluminium atau besi ringan Konstruksi kokoh dan stabil Mudah dibongkar pasang dan digunakan ulang 6. Desain Desain grafis informatif dan komunikatif Menggunakan identitas visual instansi (logo dan warna resmi) Tata letak rapi dan mudah dibaca Revisi desain hingga disetujui PPK 7. Jumlah Sesuai kebutuhan dan tercantum dalam kontrak/SPK 8. Standar Mutu Kualitas cetak seragam Tidak terdapat cacat cetak atau rangka Bahan dan rangka sesuai spesifikasi 9. Pengemasan dan Pengiriman Dikemas rapi dan aman Pengiriman hingga lokasi yang ditentukan 10. Waktu Pelaksanaan Sesuai jadwal dalam kontrak/SPK 11. Pemeriksaan dan Penerimaan Pemeriksaan fisik dan kualitas Penggantian apabila terdapat kerusakan atau ketidaksesuaian 12. Serah Terima Pekerjaan Dilaksanakan setelah barang diterima dan dinyatakan sesuai Dibuktikan dengan Berita Acara Serah Terima (BAST)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 223755);
