INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62899443', 62899443, 'analyze_legacy', 'Kab. Bandung', 'kabkota', 'DINAS PEKERJAAN UMUM DAN TATA RUANG', 'Tenaga Ahli Teknik Jembatan', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Barat, Bandung (Kab.)', 136920000, 'January 2026', 'APBD', 1, 1, '1 orang / 12 bulan', 'Perancangan dan Desain Jembatan: Merancang berbagai jenis jembatan dengan pertimbangan struktural, geoteknik, dan lalu lintas, serta memilih material yang tepat sesuai dengan kondisi. Pengawasan Konstruksi: Mengawasi pelaksanaan pembangunan jembatan untuk memastikan bahwa pekerjaan dilakukan sesuai dengan desain yang telah direncanakan dan standar kualitas yang berlaku. Pemeliharaan dan Rehabilitasi Jembatan: Merencanakan dan melaksanakan kegiatan pemeliharaan rutin serta rehabilitasi jembatan yang ada untuk memastikan kinerja dan keselamatan jembatan tetap terjaga. Evaluasi dan Penyuluhan Teknologi: Melakukan penyelidikan dan evaluasi terkait kondisi tanah, struktur jembatan, dan penggunaan teknologi baru untuk meningkatkan kualitas dan efisiensi desain dan konstruksi. Penyusunan Laporan dan Dokumentasi: Membuat laporan teknis yang mendetail tentang desain, analisis, dan hasil pengujian yang dapat digunakan oleh pihak-pihak terkait dalam pengambilan keputusan. Konsultasi dan Koordinasi: Memberikan konsultasi t eknis kepada klien dan berkoordinasi dengan tim proyek lainnya untuk memastikan proyek jembatan berjalan lancar.', 'Keahlian dan Kompetensi Desain Jembatan: Kemampuan untuk merancang jembatan yang sesuai dengan kondisi geoteknik, struktural, serta kebutuhan operasional, termasuk perhitungan beban kendaraan, cuaca, dan faktor-faktor lingkungan lainnya. Analisis Struktur Jembatan: Menganalisis struktur jembatan untuk memastikan daya dukung yang memadai, kestabilan, dan keselamatan dalam menghadapi beban dinamis dan statis. Pemilihan Material: Memilih material konstruksi yang tepat untuk jembatan, seperti beton, baja, atau komposit, berdasarkan kondisi lingkungan dan beban yang akan ditanggung. Manajemen Konstruksi: Mengelola aspek teknis dari proses pembangunan jembatan, termasuk pengawasan, pengendalian kualitas, dan pemenuhan jadwal serta anggaran. Penyelidikan dan Evaluasi: Melakukan penyelidikan tanah dan evaluasi kondisi struktur jembatan untuk tujuan desain baru atau rehabilitasi jembatan yang ada. Pemeliharaan dan Rehabilitasi Jembatan: Merancang dan merencanakan kegiatan pemeliharaan dan perbaikan jembatan yang sudah ada untuk memastikan kinerja dan keselamatan jembatan tetap optimal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 225160);
