INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62126626', 62126626, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS PENANGGULANGAN KEBAKARAN DAN PENYELAMATAN', 'Pengelolaan Kerjasama dan Kehumasan Damkar (Kehumasan) Tahap 1', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 61050000, 'December 2025', 'APBD', 1, 1, '1 Orang X 6 Bulan', '1. Melakukan perencanaan konten informasi untuk website dan sosial media Damkar; 2. Melakukan pengelolaan informasi dan publikasi di website dan sosial media Damkar; 3. Menjalin hubungan dengan pihak eksternal; 4. Melakukan pengelolaan acara kegiatan pelaksanaan MoU dalam negeri; 5. Melaksanakan manajemen komunikasi krisis isu publik di media massa; 6. Melaksanakan evaluasi konten pada akun sosial media dan website resmi Damkar; 7. Menyusun hasil analisa dan identifikasi yang akan digunakan sebagai acuan dalam pengembangan strategi komunikasi dan kehumasan; 8. Melakukan evaluasi/audit komunikasi kehumasan serta pengembangan layanan strategi komunikasi dan kehumasan pada Dinas Penanggulangan Kebakaran dan Penyelamatan Provinsi DKI Jakarta; 9. Melakukan perancangan, pengumpulan materi konten/desain, pembuatan dan pengeditan melalui mobile phone atau gawai untuk sosial media dan website resmi Damkar; 10. Merespon keluhan / pertanyaan / pengaduan masyarakat yang dilakukan melalui sosial media resmi Damkar dan melakukan koordinasi dengan pihak internal sebagai acuan tindak lanjut pengaduan masyarakat; 11. Melaksanakan publikasi dan penyiaran; 12. Membuat laporan analisa dari sosial media; 13. Bekerja secara kolaboratif sebagai bagian dari seluruh tim Bidang Kerjasama dan Informasi untuk mendukung pengelolaan konten website dan sosial media DPKP; 14. Melaporkan dan mempertanggung jawabkan pelaksanaan tugas;', '1. Memiliki pengalaman kerja di bidang komunikasi media atau sejenis minimal 1 tahun (dibuktikan dengan surat keterangan pengalaman kerja dan portofolio); 2. Menguasai Copywriting; 3. Mampu melakukan perencanaan, pengelolaan informasi dan kehumasan, hubungan eksternal dan internal; 4. Mampu melakukan evaluasi / audit komunikasi kehumasan serta pengembangan layanan strategi komunikasi dan kehumasan; 5. Mampu mengelola akun-akun media sosial dan mampu merespon keluhan masyarakat (melalui akun media sosial resmi Dinas DPKP); 6. Memiliki kemampuan membuat konten menarik; 7. Menguasai basic editing dengan mobile phone atau gawai; 8. Memiliki kemampuan dan pengetahuan penggunaan software desain grafis (diutamakan); 9. Mengerti SEO dan Memiliki pengetahuan sosial media management (diutamakan); 10. Bersedia bekerja diluar jam kerja dan dapat dipanggil sewaktu-waktu apabila dibutuhkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 225506);
