INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62898447', 62898447, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Flyer  - Pengendalian', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 61050000, 'January 2026', 'APBD', 1, 1, '5000 Lembar', 'Uraian paket pekerjaan ini meliputi kegiatan pengadaan dan penyediaan flyer sebagai media informasi, sosialisasi, publikasi, atau edukasi kepada masyarakat dan/atau pemangku kepentingan terkait pelaksanaan program dan kegiatan pemerintah. Flyer yang diadakan harus memiliki kualitas cetak yang baik, desain informatif, dan materi yang mudah dipahami, serta disesuaikan dengan kebutuhan penyampaian informasi secara efektif dan menarik. Ruang Lingkup Pekerjaan meliputi: Perencanaan dan Persiapan Koordinasi dengan Pejabat Pembuat Komitmen (PPK) terkait konsep dan kebutuhan flyer. Penyesuaian konten materi sesuai arahan dan ketentuan yang berlaku. Penyusunan Desain Flyer Pembuatan desain grafis flyer yang informatif, komunikatif, dan menarik. Penyesuaian ukuran, tata letak, warna, dan elemen visual. Penyampaian desain untuk mendapatkan persetujuan sebelum proses cetak. Pencetakan Flyer Pencetakan flyer sesuai jumlah, ukuran, dan spesifikasi teknis yang ditetapkan. Menggunakan bahan dan kualitas cetak yang baik serta warna yang jelas. Pengemasan dan Pengiriman Pengemasan flyer secara rapi dan aman. Pengiriman flyer ke lokasi yang ditentukan. Pengendalian Mutu Pemeriksaan kualitas hasil cetak. Perbaikan atau penggantian apabila terdapat ketidaksesuaian dengan spesifikasi. Serah Terima Pekerjaan Serah terima flyer yang dituangkan dalam Berita Acara Serah Terima (BAST). Dengan terlaksananya paket pekerjaan ini, diharapkan flyer yang dihasilkan dapat digunakan secara optimal sebagai sarana komunikasi dan sosialisasi kegiatan kepada masyarakat.', 'Pengadaan Flyer 1. Nama Pekerjaan Pengadaan Flyer 2. Jenis Pekerjaan Pengadaan Barang Cetakan (Media Informasi) 3. Fungsi Sebagai media informasi, sosialisasi, dan publikasi kegiatan/program kepada masyarakat dan/atau pemangku kepentingan. 4. Spesifikasi Produk 4.1 Ukuran Ukuran standar: A5 (14,8 × 21 cm) atau A4 (21 × 29,7 cm) Ukuran lain menyesuaikan kebutuhan dan persetujuan PPK 4.2 Bahan Kertas Kertas Art Paper / Art Carton Gramatur minimal 120 gsm – 150 gsm Kertas berkualitas baik, tidak mudah sobek, dan permukaan halus 4.3 Pencetakan Cetak full color (CMYK) Satu sisi atau dua sisi (sesuai kebutuhan) Warna tajam dan jelas, tidak pudar Resolusi cetak tinggi 4.4 Finishing Potong rapi sesuai ukuran Finishing standar tanpa lipatan Finishing tambahan (opsional): lipat, laminasi doff/glossy (jika dipersyaratkan) 5. Desain Desain grafis informatif dan komunikatif Menggunakan identitas visual instansi (logo, warna resmi) Tata letak rapi dan mudah dibaca Materi konten disesuaikan dengan arahan PPK Revisi desain minimal 1–2 kali sampai disetujui 6. Jumlah Jumlah cetak sesuai kebutuhan dan tercantum dalam kontrak/SPK 7. Standar Mutu Kualitas cetak konsisten untuk seluruh flyer Tidak terdapat cacat cetak (buram, warna tidak merata, tinta luntur) Hasil cetak sesuai desain yang telah disetujui 8. Pengemasan dan Pengiriman Dikemas rapi dan aman Pengiriman sampai ke lokasi yang ditentukan Kondisi flyer tetap baik saat diterima 9. Waktu Pelaksanaan Sesuai jadwal yang ditetapkan dalam kontrak/SPK 10. Pemeriksaan dan Penerimaan Pemeriksaan kesesuaian jumlah dan kualitas Penggantian apabila terdapat kerusakan atau ketidaksesuaian spesifikasi 11. Serah Terima Pekerjaan Dilaksanakan setelah barang diterima dan dinyatakan sesuai Dibuktikan dengan Berita Acara Serah Terima (BAST)', 36050000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 227620);
