INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62898109', 62898109, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Pengadaan Kamera Digital', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 29999999, 'May 2026', 'APBD', 1, 1, '1 Unit', 'Pengadaan Kamera Digital Uraian pekerjaan Pengadaan Kamera Digital ini meliputi kegiatan pengadaan, penyediaan, pengiriman, dan penyerahan perangkat kamera digital yang digunakan untuk mendukung kegiatan dokumentasi foto dan/atau video dalam rangka pelaksanaan tugas kedinasan, kegiatan lapangan, publikasi, serta pendokumentasian kegiatan resmi pada perangkat daerah. Pekerjaan ini mencakup penyediaan kamera digital dengan kualitas hasil gambar yang baik, mudah dioperasikan, serta memiliki fitur yang mendukung dokumentasi kegiatan secara optimal. Perangkat kamera yang disediakan harus dalam kondisi baru, bukan bekas atau rekondisi, serta memenuhi spesifikasi teknis yang dipersyaratkan. Ruang lingkup pekerjaan meliputi: Pengadaan kamera digital sesuai jumlah dan spesifikasi teknis yang ditetapkan dalam kontrak atau surat pesanan. Menjamin kamera digital dalam kondisi baru, asli pabrikan, dan belum pernah digunakan. Penyediaan kamera digital lengkap dengan aksesori standar pabrikan. Menjamin kualitas hasil foto dan/atau video yang tajam, jelas, dan sesuai kebutuhan dokumentasi kegiatan. Pengiriman dan penyerahan kamera digital ke lokasi yang ditentukan oleh Pejabat Pembuat Komitmen (PPK) atau Pejabat Pengadaan dalam kondisi siap digunakan. Pelaksanaan pemeriksaan fisik, uji fungsi dasar, dan konfigurasi awal perangkat. Penggantian unit kamera digital apabila ditemukan kerusakan, cacat produksi, atau ketidaksesuaian spesifikasi pada saat pemeriksaan. Pelaksanaan serah terima barang yang dituangkan dalam Berita Acara Serah Terima (BAST) sesuai ketentuan yang berlaku. Dengan terlaksananya pekerjaan ini, diharapkan ketersediaan kamera digital dapat mendukung kegiatan dokumentasi dan pelaporan kegiatan secara efektif, akurat, dan profesional.', 'Kamera Digital 1. Nama Barang Kamera Digital 2. Jenis Kamera digital mirrorless atau DSLR Dapat digunakan untuk dokumentasi foto dan video kegiatan kedinasan 3. Kondisi Baru (brand new) Bukan barang bekas atau rekondisi Produk resmi pabrikan 4. Sensor Sensor APS-C atau Full Frame Resolusi efektif minimal 24 megapiksel 5. Prosesor Gambar Prosesor gambar generasi terbaru atau setara Mendukung pemrosesan gambar cepat dan akurat 6. Lensa Lensa kit standar disertakan Rentang fokus setara 18–55 mm atau setara Auto focus (AF) dan manual focus (MF) 7. Sistem Fokus Sistem autofocus hybrid (phase detection & contrast detection) Titik fokus minimal 100 titik atau setara Mendukung face detection dan subject tracking 8. ISO Rentang ISO minimal 100 – 25.600 Mendukung kondisi cahaya rendah 9. Kecepatan Rana Kecepatan rana minimal 1/4.000 detik Mode continuous shooting tersedia 10. Perekaman Video Resolusi video minimal 4K (30 fps) Full HD hingga 60 fps Format video umum (MP4/MOV) 11. Layar Layar LCD minimal 3 inci Resolusi tinggi Dapat diputar atau dimiringkan (tilt/vari-angle) 12. Viewfinder Electronic Viewfinder (EVF) atau Optical Viewfinder Resolusi memadai untuk framing akurat 13. Media Penyimpanan Slot kartu memori SD/SDHC/SDXC Mendukung kapasitas besar 14. Konektivitas USB HDMI Wi-Fi dan/atau Bluetooth untuk transfer data 15. Sistem Daya Baterai rechargeable Charger atau adaptor disertakan Daya tahan baterai sesuai standar pabrikan 16. Aksesori Standar Bodi kamera Lensa Baterai Charger/adaptor Strap kamera Penutup lensa Kabel data Buku manual 17. Kompatibilitas Kompatibel dengan tripod standar Mendukung lensa tambahan sesuai sistem kamera 18. Garansi Garansi resmi pabrikan minimal 1 (satu) tahun Layanan servis resmi tersedia di Indonesia 19. Pengiriman dan Serah Terima Kamera diserahkan dalam kondisi siap pakai Dilakukan uji fungsi dasar (foto & video) Serah terima dituangkan dalam Berita Acara Serah Terima (BAST)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 228326);
