INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62131375', 62131375, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'PUSAT PELAPORAN DAN ANALISIS TRANSAKSI KEUANGAN', 'Pengadaan Layanan Internet Wisma Mandiri pada Pusat Pelaporan dan Analisis Transaksi Keuangan Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 270000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', 'Layanan Internet Wisma Mandiri untuk lantai 5 dan 6 dengan Dedicated Internet 100 Mbps', '• Bandwith Internet Dedicated Fiber Optic 100 Mbps (domestik dan internasional) • Bandwith yang akan digunakan oleh PPATK yaitu dengan CIR (Committed Information Rate) 1:1 • Layanan internet • Media jaringan (backbone) yang digunakan untuk menghubungkan data center ISP dengan IIX/OpenIXP menggunakan Fiber Optic milik sendiri, atau campuran dengan milik ISP (perusahaan) lain • Koneksi menggunakan Ethernet RJ45 dapat dihubungkan dengan router/switch Ketentuan Pengenaan Denda Downtime: Apabila layanan internet yang disediakan mengalami downtime, Penyedia dikenakan denda dengan ketentuan perhitungan sebagai berikut: Denda=(A-Av)/C x B Dengan keterangan sebagai berikut: A: Jumlah jam gangguan dalam bulan gangguan Av: (100% - % tingkat availability) x jumlah jam Bulan gangguan B: Biaya langganan bulanan C: Jumlah jam dalam bulan gangguan % Tingkat Availability sesuai SLA sebesar 99,9% Denda dihitung sejak gangguan terjadi berdasarkan catatan/log sistem PPATK sampai gangguan tersebut dapat diatasi dan akan dipotong langsung pada saat pembayaran tagihan bulan berkenaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 228533);
