INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62132589', 62132589, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'KELURAHAN LEBAK BULUS - JAKSEL', 'Pembayaran Gaji PJLP Ruang Interaksi Warga/RPTRA', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 841894716, 'December 2025', 'APBD', 1, 1, '12 Paket', 'Menyelesaikan pekerjaan sebagai Tuan Rumah RPTRA, multitasking melaksanakan segala aspek operasional dan administrasi (kebersihan, keamanan, pendataan, pemantauan, pelayanan, dll) dengan perlakuan yang responsif anak dan gender, di wilayah Kelurahan Lebak Bulus, serta melaksanakan tugas lainnya baik lisan dan tertulis dari Pimpinan Pemerintah Provinsi DKI Jakarta, baik di tingkat Kelurahan, Kecamatan, Kota dan Provinsi. a. Menyusun rencana kegiatan dan anggaran RPTRA untuk diajukan kepada Pengurus RPTRA Tingkat Kelurahan; b. Melaksanakan kegiatan Pelayanan RPTRA; c. Membuka dan menutup fasilitas RPTRA; d. Memonitor Pemanfaatan sarana dan prasarana RPTRA; e. Mengevaluasi pelaksanaan kegiatan pelayanan RPTRA; f. Menjaga prasarana dan sarana RPTRA; g. Memfasilitasi pelatihan, penyuluhan, sosialisasi dan pendampingan; h. Memberikan komunikasi, informasi, dan edukasi kepada pemanfaat dan pengunjung RPTRA; i. Memulai dan mengakhiri kegiatan sehari-hari di RPTRA berdasarkan Shift; j. Melaporkan kerusakan prasarana dan sarana RPTRA kepada pengurus RPTRA Tingkat Kelurahan; k. Melaporkan pelaksanaan kegiatan pelayanan harian RPTRA kepada pengurus RPTRA Tingkat Kelurahan; l. Melaporkan permasalahan kegiatan pelayanan RPTRA kepada pengurus RPTRA Tingkat Kelurahan; m. Melaporkan pelaksanaan tugas Pengelola RPTRA kepada pengurus RPTRA Tingkat Kelurahan secara periodik.', '1. Memiliki Akun SIKAP (Sistem Informasi Kinerja Penyedia) 2. Memiliki Kartu Tanda Penduduk (KTP) Provinsi Daerah Khusus Ibukota Jakarta, diutamakan yang berdomisili di sekitar lokasi RPTRA; 3. Mempunyai status valid keterangan Wajib Pajak berdasarkan hasil Konfirmasi Status Wajib Pajak; 4. Kualifikai Usaha Kecil; 5. Ijazah minimal SMA/Sederajat (upload disistem LPSE) 6. Daftar Riwayat Hidup/Biodata lengkap (upload disistem LPSE) 7. Memuat Photo terbaru apabila sudah ditetapkan sebagai pemenang 8. Memiliki Surat Keterangan Sehat dari Pusat Kesehatan Masyarakat/Puskesmas (upload disistem LPSE); 9. Menandatangani Surat Pernyataan (dilampirkan setelah ditetapkan sebagai pemenang)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 229428);
